INSERT OR REPLACE INTO LocalizedText (Language, Tag, Text) VALUES
    ('en_US', 'LOC_VICTORY_HEGEMONY_NAME', 'Hegemony Victory'),
    ('en_US', 'LOC_VICTORY_HEGEMONY_DESCRIPTION', 'To achieve a Hegemony Victory, surpass the combined totals of all surviving rivals in military strength and in Food, Production, Science, Culture, and Faith per turn. Your net Gold per turn must also exceed their combined positive net income. Own at least as many completed world wonders still standing and be suzerain of at least as many surviving city-states as all surviving rivals combined.'),
    ('en_US', 'LOC_VICTORY_HEGEMONY_BLURB', 'The winning civilization has united prosperity, knowledge, faith, and military might. Its wonders bear witness to an age of achievement, and city-states look to it for leadership. Its hegemony will shape the world for generations.'),
    ('zh_Hans_CN', 'LOC_VICTORY_HEGEMONY_NAME', '霸权胜利'),
    ('zh_Hans_CN', 'LOC_VICTORY_HEGEMONY_DESCRIPTION', '要取得霸权胜利，您的军力以及每回合的食物、生产力、科技、文化和信仰，均须超过所有存活对手的相应合计。每回合的净金币收入也须超过对手的正净收入之和。您拥有的已完工且仍存在的世界奇观数量，以及您担任宗主的存活城邦数量，均须不少于所有存活对手的相应合计。'),
    ('zh_Hans_CN', 'LOC_VICTORY_HEGEMONY_BLURB', '繁荣、知识、信仰和军力汇聚于这个获胜文明。宏伟的奇观见证它的盛世，众多城邦拥戴它为宗主。它的霸权将在未来数代塑造这个世界。');
